const wh = $('Webhook').first().json;
const body = wh.body ?? wh;

const question = String(body.question ?? body.chatInput ?? body.message ?? "").trim();
// Strict user choice from chatbot (zero auto-detection heuristics)
const userLang = String(body.language ?? "English").trim();
const language = userLang.toLowerCase() === "amharic" || userLang.toLowerCase() === "am" ? "Amharic" : "English";

return [{
  json: {
    question,
    language,
    sessionId: body.sessionId ?? $execution.id,
    channel: body.channel ?? "web",
  },
}];

