={{ (() => {
  const raw = $json.output || '';
  const hasForm = Boolean(/\[\[\s*FORM\s*\]\]/i.test(raw));
  const hasManageForm = Boolean(/\[\[\s*MANAGE_FORM/i.test(raw));
  const slotsMatch = raw.match(/\[\[\s*SLOTS\s*:\s*([^\]]+)\]\]/i);
  let slots = null;
  if (slotsMatch) {
    slots = slotsMatch[1].split(',').map(s => {
      const parts = s.split('|').map(p => p.trim());
      return { label: parts[0] || '', slot_start: parts[1] || parts[0] || '' };
    }).filter(x => x.label);
  }
  const clean = raw
    .replace(/\[\[\s*FORM\s*\]\]/gi, '')
    .replace(/\[\[\s*MANAGE_FORM[^\]]*\]\]/gi, '')
    .replace(/\[\[\s*SLOTS[^\]]*\]\]/gi, '')
    .trim();
  return {
    output: clean,
    reply: clean,
    showForm: hasForm,
    showManageForm: hasManageForm,
    manageAction: /reschedule|postpone|ቀይር|አዛውር/i.test(raw) ? 'reschedule' : 'cancel',
    slots: slots,
    sessionId: $('Code in JavaScript').first().json.sessionId,
    pendingSlot: $json.pendingSlot || null,
    error: null
  };
})() }}

parameters.jsCode:
// Detects the form submission and loads the slot the patient chose.
const base = $input.first().json;
const wh = $('Webhook').first().json;
const body = wh.body ?? wh;
const sid = String(base.sessionId || '');
const text = String(base.question || '').trim();

const store = $getWorkflowStaticData('global');
store.pending = store.pending || {};
const nowMs = Date.now();
for (const k of Object.keys(store.pending)) {
  if (nowMs - (store.pending[k].t || 0) > 2 * 3600 * 1000) delete store.pending[k];
}

// pending slot: echoed by the frontend if available, otherwise remembered per session
const bp = body.pendingSlot;
const pending = (bp && bp.slot_start)
  ? { slot_start: String(bp.slot_start), category: String(bp.category || 'checkup'), reason: String(bp.reason || '') }
  : (store.pending[sid] || null);

// form fields: structured payload first, typed message as fallback
const f = (body.form && typeof body.form === 'object') ? body.form : body;
const pick = (...ks) => { for (const k of ks) { if (f[k] !== undefined && f[k] !== null && String(f[k]).trim() !== '') return String(f[k]).trim(); } return ''; };
let name = pick('name', 'fullName', 'full_name');
if (!name) name = [pick('firstName', 'first_name'), pick('lastName', 'last_name')].filter(Boolean).join(' ');
let phone = pick('phone', 'phoneNumber', 'phone_number');
let email = pick('email');
const explicit = !!(name || phone || body.type === 'form' || body.formSubmitted);

if (!phone) { const pm = text.match(/(?:\+?251|0)?[\s-]?[79](?:[\s-]?\d){8}/); if (pm) phone = pm[0].trim(); }
if (!email) { const em = text.match(/[^\s@,]+@[^\s@,]+\.[^\s@,]{2,}/); if (em) email = em[0]; }
if (!name && phone) {
  let rest = text.replace(phone, ' ');
  if (email) rest = rest.replace(email, ' ');
  name = rest.replace(/\b(my name is|full name|name|phone number|phone|mobile|email|and|is)\b/gi, ' ')
    .replace(/[0-9+@,:;()_.\-]/g, ' ').replace(/\s+/g, ' ').trim();
}
if (!/\p{L}{2,}/u.test(name)) name = '';

const isForm = !!(explicit || (pending && phone));
let formProblem = '';
if (isForm && !pending) formProblem = 'no_slot';
else if (isForm && !name) formProblem = 'missing_name';
else if (isForm && !phone) formProblem = 'missing_phone';
const canBook = !!(isForm && pending && name && phone);

return [{ json: { ...base, isForm, canBook, formProblem, pending, name, phone, email } }];

// Builds the patient reply from the REAL booking result. No AI involved.
const D = $('Detect Form').first().json;
const R = D.canBook ? ($json || {}) : {};
const am = D.language === 'Amharic';
const PHONE = '+251 11 555 0123';
const sid = String(D.sessionId || '');
const store = $getWorkflowStaticData('global');
store.pending = store.pending || {};

const T = am ? {
  ok: (l, r, m) => 'ቀጠሮዎ ተረጋግጧል። ' + l + '። የቀጠሮ ቁጥርዎ ' + r + ' ነው።' + (m ? ' የማረጋገጫ ኢሜይል ወደ እርስዎ ይላካል።' : '') + ' በዴንቶራ የጥርስ ክሊኒክ በደስታ እንጠብቅዎታለን።',
  taken: 'ይቅርታ፣ ይህ ሰዓት ሊያዝ አይችልም። እባክዎ ሌላ ቀን ወይም ሰዓት ይንገሩኝ፣ እኔም አረጋግጣለሁ።',
  noSlot: 'እባክዎ መጀመሪያ የሚፈልጉትን ቀንና ሰዓት ይንገሩኝ፣ እኔም አረጋግጣለሁ።',
  name: 'እባክዎ ሙሉ ስምዎን በቅጹ ውስጥ ያስገቡ።',
  phone: 'የስልክ ቁጥሩ ትክክል አይመስልም። እባክዎ በቅጹ ውስጥ በትክክል ያስገቡ፣ ለምሳሌ 0912345678።',
  email: 'የኢሜይል አድራሻው ትክክል አይመስልም። እባክዎ በቅጹ ውስጥ እንደገና ያስገቡ።',
  fail: 'ይቅርታ፣ ቀጠሮውን አሁን ማስያዝ አልቻልኩም። እባክዎ በ ' + PHONE + ' ይደውሉልን።',
} : {
  ok: (l, r, m) => 'Your appointment is confirmed. ' + l + '. Your booking reference is ' + r + '.' + (m ? ' A confirmation email is on its way.' : '') + ' We look forward to seeing you at Denttora Dental Clinic.',
  taken: 'Sorry, that time cannot be booked. Please tell me another day or time and I will check it for you.',
  noSlot: 'Please tell me which day and time you would like first, and I will check it in the calendar.',
  name: 'Please enter your full name in the form below.',
  phone: 'That phone number does not look valid. Please enter it again in the form below, for example 0912345678.',
  email: 'That email does not look valid. Please enter it again in the form below.',
  fail: 'Sorry, I could not complete the booking just now. Please try again or call us on ' + PHONE + '.',
};

let out = '';
let keep = false;
if (D.formProblem === 'no_slot') out = T.noSlot;
else if (D.formProblem === 'missing_name') { out = T.name + ' [[FORM]]'; keep = true; }
else if (D.formProblem === 'missing_phone') { out = T.phone + ' [[FORM]]'; keep = true; }
else if (R.ok === true && R.action === 'book' && R.reference) {
  out = T.ok(R.label, R.reference, R.email_will_be_sent);
  delete store.pending[sid];
} else {
  const e = typeof R.error === 'string' ? R.error : '';
  if (e === 'invalid_phone') { out = T.phone + ' [[FORM]]'; keep = true; }
  else if (e === 'missing_name') { out = T.name + ' [[FORM]]'; keep = true; }
  else if (e === 'invalid_email' || e === 'email_typo') { out = T.email + ' [[FORM]]'; keep = true; }
  else if (['slot_taken', 'too_soon', 'closed_day', 'outside_hours', 'invalid_slot', 'too_far'].includes(e)) { out = T.taken; delete store.pending[sid]; }
  else { out = T.fail; delete store.pending[sid]; }
}
return [{ json: { output: out, pendingSlot: keep ? D.pending : null } }];

// Runs after the AI agent. The AI can never show a fake reference, unverified slots, or an unverified booking form.
const D = $('Detect Form').first().json;
const sid = String(D.sessionId || '');
const am = D.language === 'Amharic';
const PHONE = '+251 11 555 0123';
const store = $getWorkflowStaticData('global');
store.pending = store.pending || {};

let out = String($json.output || '').trim();
const steps = $json.intermediateSteps || [];
const obs = steps
  .map((s) => (typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation || '')))
  .join(' ');

// Check whether Booking tool was actually invoked in this turn
const hasBookingToolObs = /get_slots|total_free|duration_min|slot_start/i.test(obs);

// 1) A booking reference must come from a real tool result
const refs = out.match(/DC-\d{6}/g) || [];
if (refs.some((r) => !obs.includes(r))) {
  out = am
    ? 'ይቅርታ፣ አሁን ማጠናቀቅ አልቻልኩም። እባክዎ እንደገና ይሞክሩ ወይም በ ' + PHONE + ' ይደውሉልን።'
    : 'Sorry, I could not complete that just now. Please try again or call us on ' + PHONE + '.';
  return [{ json: { output: out, pendingSlot: null } }];
}

// 2) Anti-hallucination slot guard: if [[SLOTS: ...]] appears, it MUST come from a live get_slots call
const slotsMatch = out.match(/\[\[\s*SLOTS\s*:\s*([^\]]+)\]\]/i);
if (slotsMatch) {
  if (!hasBookingToolObs) {
    // Agent fabricated slots without executing Booking tool
    out = am
      ? 'የክሊኒኩን የቀን መቁጠሪያ በትክክል እየፈተሽኩ ነው። እባክዎ የሚፈልጉትን ቀን ይንገሩኝ፣ ወይም በቀጥታ በ ' + PHONE + ' ይደውሉልን።'
      : 'I am checking the live clinic calendar for you. Which day would you like to check, or you can call us directly on ' + PHONE + '.';
    return [{ json: { output: out, pendingSlot: null } }];
  }
}

// 3) Form is only allowed for a slot that get_slots returned in THIS turn
const m = out.match(/\[\[\s*SLOT\s*:\s*([^|\]]+?)\s*\|\s*([^|\]]*?)\s*\|\s*([^\]]*?)\s*\]\]/i);
out = out.replace(/\[\[\s*SLOT[^\]]*\]\]/gi, '').trim();
let pendingSlot = null;
if (m && obs.includes(m[1].trim())) {
  pendingSlot = { slot_start: m[1].trim(), category: m[2].trim() || 'checkup', reason: m[3].trim() };
  store.pending[sid] = { ...pendingSlot, t: Date.now() };
}
if (/\[\[\s*FORM\s*\]\]/i.test(out) && !pendingSlot) {
  out = am
    ? 'እባክዎ የሚፈልጉትን ቀንና ሰዓት ይንገሩኝ፣ መጀመሪያ በቀን መቁጠሪያው ላይ አረጋግጣለሁ።'
    : 'Which day and time would you like? I will check it in the calendar first.';
}
return [{ json: { output: out, pendingSlot } }];
